  {all_else_equal_1 : zk1mxe7x.SameCircumstancesExceptWealth (Subtype.val p1_1) (Subtype.val p2_1)},
  zk1mxe7x.TwoPeopleDifferingInWealth.mk p1 p2 p1Character p2Character p1_is_rich p2_is_not p1_has_character
